    if(pathname==="/api/bands"&&method==="POST"){if(user.role!=="admin")return bad("Apenas o administrador pode cadastrar bandas.",403);const body=await readBody(request),name=String(body.name||"").trim(),password=String(body.password||"");if(name.length<2||name.length>80)return bad("O nome da banda precisa ter entre 2 e 80 caracteres.");if(name.toLowerCase()==="admin")return bad("Esse nome est√° reservado ao administrador.");if(!validPassword(password))return bad("A senha precisa ter de 8 a 128 caracteres.");const id=crypto.randomUUID(),salt=randomHex(),hash=await passwordHash(password,salt);try{await env.DB.batch([env.DB.prepare("INSERT INTO bands (id,name) VALUES (?1,?2)").bind(id,name),env.DB.prepare("INSERT INTO accounts (id,username,role,band_id,salt,password_hash) VALUES (?1,?2,'band',?1,?3,?4)").bind(id,name,salt,hash),env.DB.prepare("INSERT INTO band_data (band_id,data_json) VALUES (?1,?2)").bind(id,JSON.stringify(body.data&&typeof body.data==="object"?body.data:JSON.parse(bandDefaults())))]);return response({band:{id,name},ok:true},201)}catch{return bad("J√° existe uma banda com esse nome.",409)}}
    const bandMatch=pathname.match(/^\/api\/bands\/([^/]+)(?:\/(password))?$/);if(bandMatch){if(user.role!=="admin")return bad("Apenas o administrador pode administrar bandas.",403);const bandId=decodeURIComponent(bandMatch[1]);if(bandMatch[2]==="password"&&method==="PUT"){const body=await readBody(request),password=String(body.password||"");if(!validPassword(password))return bad("A senha precisa ter de 8 a 128 caracteres.");const salt=randomHex(),hash=await passwordHash(password,salt),result=await env.DB.prepare("UPDATE accounts SET salt=?1,password_hash=?2 WHERE band_id=?3 AND role='band'").bind(salt,hash,bandId).run();return response({ok:true},result.meta?.changes?200:404)}if(method==="DELETE"){await env.DB.batch([env.DB.prepare("DELETE FROM band_data WHERE band_id=?1").bind(bandId),env.DB.prepare("DELETE FROM accounts WHERE band_id=?1").bind(bandId),env.DB.prepare("DELETE FROM bands WHERE id=?1").bind(bandId)]);return response({ok:true})}return bad("Opera√ß√£o n√£o encontrada.",404)}
    if(pathname==="/api/data"&&(method==="GET"||method==="PUT")){let bandId=user.role==="admin"?String(searchParams.get("bandId")||""):user.band_id;if(!bandId)return bad("Selecione uma banda.",400);if(user.role!=="admin"&&bandId!==user.band_id)return bad("Voc√™ n√£o tem acesso a essa banda.",403);const band=await env.DB.prepare("SELECT id FROM bands WHERE id=?1").bind(bandId).first();if(!band)return bad("Banda n√£o encontrada.",404);if(method==="GET"){const row=await env.DB.prepare("SELECT data_json FROM band_data WHERE band_id=?1").bind(bandId).first();let data={};try{data=JSON.parse(row?.data_json||bandDefaults())}catch{}return response({data})}const body=await readBody(request);if(!body||typeof body!=="object"||Array.isArray(body))return bad("Formato de dados inv√°lido.");const serialized=JSON.stringify(body);if(serialized.length>1_500_000)return bad("Os dados da banda excedem o limite de 1,5 MB.");await env.DB.prepare("INSERT INTO band_data (band_id,data_json,updated_at) VALUES (?1,?2,CURRENT_TIMESTAMP) ON CONFLICT(band_id) DO UPDATE SET data_json=excluded.data_json,updated_at=CURRENT_TIMESTAMP").bind(bandId,serialized).run();return response({ok:true})}
