function textAsset(base64,type){const binary=atob(base64);const bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));return new Response(new TextDecoder().decode(bytes),{headers:{"Content-Type":type,"Cache-Control":"no-cache"}})}
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname.startsWith("/api/"))return api(request,env,url);const path=url.pathname==="/"||url.pathname==="/index.html"?"index.html":url.pathname.replace(/^\//,"");const type={"index.html":"text/html; charset=utf-8","styles.css":"text/css; charset=utf-8","auth.css":"text/css; charset=utf-8","app.js":"text/javascript; charset=utf-8","auth.js":"text/javascript; charset=utf-8"}[path];if(type&&ASSETS[path])return textAsset(ASSETS[path],type);return new Response("Not found",{status:404})}};
